[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Path);$x=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json
if($null -ne $x.offer.PSObject.Properties['extra']){throw 'PORTABLE_SCHEMA_ADDITIONAL_PROPERTY'};if($x.project_id -notmatch '^PROJECT-' -or $x.story_id -notmatch '^STORY-' -or $x.classification -ne 'synthetic' -or $x.status -ne 'hypercare'){throw 'PORTABLE_IDENTITY_INVALID'};if(@($x.offer.versions).Count -lt 3){throw 'PORTABLE_OFFER_VERSIONS_MINITEMS'};if(@($x.pages).Count -ne 19 -or @($x.tickets).Count -ne 17 -or @($x.timeline).Count -ne 15 -or @($x.hypercare).Count -ne 3){throw 'PORTABLE_COUNT_INVALID'}
$pageById=@{};$pageIds=@();$paths=@();foreach($p in @($x.pages)){if($pageById.ContainsKey($p.id)){throw 'PORTABLE_DUPLICATE_ID'};$pageById[$p.id]=$p;$pageIds+=$p.id;if($paths -contains $p.sourcePath){throw 'PORTABLE_DUPLICATE_SOURCEPATH'};$paths+=$p.sourcePath;if($p.sourcePath -match '(^[A-Za-z]:|^/|\.\.|\\)'){throw 'PORTABLE_UNSAFE_PATH'};if(-not(Test-Path (Join-Path $d $p.sourcePath) -PathType Leaf)){throw 'PORTABLE_PAGE_MISSING'};$txt=Get-Content (Join-Path $d $p.sourcePath) -Raw;if($txt -notmatch "id:\s*$($p.id)" -or $txt -notmatch "version:\s*$($p.version)" -or $txt -notmatch "status:\s*$($p.status)"){throw 'PORTABLE_PAGE_METADATA'}};foreach($p in @($x.pages)){$seen=@{};$cur=$p;while($cur.parent){if($seen.ContainsKey($cur.id)){throw 'PORTABLE_PAGE_CYCLE'};$seen[$cur.id]=$true;if(-not $pageById.ContainsKey($cur.parent)){throw 'PORTABLE_PAGE_PARENT'};$cur=$pageById[$cur.parent]}}
$ticketIds=@($x.tickets|% id);$valid=$pageIds+$ticketIds+@($x.evidence|% id)+@($x.sessions|% id)+@($x.decisions|% id)+@($x.deliverables|% id);$hours=0;$cost=0;foreach($t in @($x.tickets)){if([string]::IsNullOrWhiteSpace($t.reporter)-or [string]::IsNullOrWhiteSpace($t.assignee)-or @($t.acceptance).Count -eq 0-or @($t.evidence).Count -eq 0){throw 'PORTABLE_TICKET_FIELDS'};$h=@($t.status_history);for($i=1;$i -lt $h.Count;$i++){if([datetime]$h[$i].time -lt [datetime]$h[$i-1].time){throw 'PORTABLE_STATUS_HISTORY'}};if($h[0].status -ne 'open'-or $h[-1].status -ne $t.status){throw 'PORTABLE_STATUS_TERMINAL'};if($t.status -in @('closed','done') -and @($t.comments|? type -eq 'closing').Count -ne 1){throw 'PORTABLE_CLOSING_COMMENT'};foreach($c in @($t.comments)){if([string]::IsNullOrWhiteSpace($c.author_role)-or [string]::IsNullOrWhiteSpace($c.text)){throw 'PORTABLE_COMMENT_FIELDS'}};foreach($w in @($t.worklogs)){if($w.hours -le 0){throw 'PORTABLE_WORKLOG_INVALID'};$hours+=$w.hours;$cost+=$w.cost}};if($hours -ne 80 -or $cost -ne 9600 -or $x.offer.actual_hours -ne $hours -or $x.offer.actual_cost -ne $cost){throw 'PORTABLE_COST_MISMATCH'}
foreach($e in @($x.timeline)){foreach($r in @($e.references)){if($valid -notcontains $r){throw 'PORTABLE_TIMELINE_REFERENCE'}}};for($i=1;$i -lt @($x.timeline).Count;$i++){if([datetime]$x.timeline[$i].time -lt [datetime]$x.timeline[$i-1].time){throw 'PORTABLE_TIMELINE_ORDER'}};if([datetime]$x.timeline[0].time -lt [datetime]$x.offer.start_time -or [datetime]$x.timeline[-1].time -gt [datetime]$x.offer.end_time){throw 'PORTABLE_TIMELINE_RANGE'};foreach($h in @($x.hypercare)){if($h.status -ne 'closed'-or $h.go_no_go -ne 'GO'-or $ticketIds -notcontains $h.tickets[0]-or $pageIds -notcontains $h.daily_page){throw 'PORTABLE_HYPERCARE_EXIT'}};if(@($x.tickets|? {$_.priority -in @('P1','P2') -and $_.status -notin @('closed','done')}).Count){throw 'PORTABLE_HYPERCARE_OPEN_HIGH_PRIORITY'};$inv=@{'page-ticket'='ticket-page';'ticket-page'='page-ticket'};foreach($e in @($x.graph)){if($valid -notcontains $e.from-or $valid -notcontains $e.to){throw 'PORTABLE_GRAPH_ORPHAN'};if(-not $inv.ContainsKey($e.type)){throw 'PORTABLE_GRAPH_RELATION'};if(@($x.graph|? {$_.from -eq $e.to -and $_.to -eq $e.from -and $_.type -eq $inv[$e.type]}).Count -ne 1){throw 'PORTABLE_GRAPH_INVERSE'}};Write-Host 'PASS: Portable external project story conformance validated read-only.'
